from databricks.sdk import WorkspaceClient

w = WorkspaceClient()
run_id = 794256342782864

# Get run state and tasks
run_state = w.jobs.get_run(run_id=run_id)
print('Tasks:')
for task in (run_state.tasks or []):
    print(f'  {task.task_key}: run_id={task.run_id}, state={task.state}')
    # Get task run output
    if task.run_id:
        try:
            out = w.jobs.get_run_output(run_id=task.run_id)
            if out.notebook_output:
                print('  Output:', out.notebook_output.result[:500] if out.notebook_output.result else 'None')
            if out.error:
                print('  Error:', out.error[:500])
            if out.error_trace:
                print('  Trace:', out.error_trace[:1000])
        except Exception as e:
            print(f'  Output error: {e}')
