from databricks.sdk import WorkspaceClient

w = WorkspaceClient()

# Try the raw REST API for Synced Tables
try:
    resp = w.api_client.do(
        method='GET',
        path='/api/2.0/catalog/tables/workspace.mlpab88e583.ccpred739ee9'
    )
    print('Table info:', resp.get('table_type'), resp.get('properties', {}).get('delta.enableChangeDataFeed'))
except Exception as e:
    print(f'Error: {e}')

# Try creating synced table via raw API
try:
    body = {
        'name': 'workspace.mlpab88e583.ccpred739ee9_synced',
        'spec': {
            'source_table_full_name': 'workspace.mlpab88e583.ccpred739ee9',
            'primary_key_columns': ['transaction_id'],
            'run_triggered': {}
        }
    }
    resp = w.api_client.do(
        method='POST',
        path='/api/2.0/catalog/synced-tables',
        body=body
    )
    print('Synced table created:', resp)
except Exception as e:
    print(f'Synced table error: {e}')

# Try the online tables API path (the replacement for online tables)
try:
    resp = w.api_client.do(
        method='GET',
        path='/api/2.0/catalog/online-tables'
    )
    print('Online tables:', resp)
except Exception as e:
    print(f'Online tables GET error: {e}')
"
